Section FW.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (m : fmem) (WK DT SY tl : Z) (rank : list Z) (syms : list (option Z)) (js jt : list byte) (ncells : nat).
  Variable POST : machine_state -> Prop.
  Notation SP := (bv_unsigned sp).
  Hypothesis HTL : 1 <= tl <= 12.
  Hypothesis LR : zlen rank = 13.
  Hypothesis RR : Forall (fun v => 0 <= v <= 256) rank.
  Hypothesis HJT : length jt = (2 * ncells)%nat.
  Hypothesis HJS : length js = length syms.
  Hypothesis LSY : length syms = 256%nat.
  Hypothesis HSYR : forall i v, nth i syms None = Some v -> 0 <= v < 256.
  Hypothesis HNC : Z.of_nat ncells <= 8192.
  Hypothesis HDT : 0 < DT /\ DT + 4 + 2 * Z.of_nat ncells <= 2^47.
  Hypothesis HSY : 0 < SY /\ SY + zlen js <= 2^47.
  Hypothesis HWK : 0 < WK /\ WK + 52 <= 2^47.
  Hypothesis DJ : DT + 4 + 2 * Z.of_nat ncells <= SY \/ SY + zlen js <= DT + 4.
  Hypothesis DJW : DT + 4 + 2 * Z.of_nat ncells <= WK \/ WK + 52 <= DT + 4.
  Hypothesis HSP : DT + 4 + 2 * Z.of_nat ncells <= SP /\ SP <= 2^47.
  Hypothesis DWS : WK + 52 <= SP.
  Hypothesis RKA0 : u32arr psegs m WK (map (Z_to_bv 64) rank).
  Hypothesis SLOT0 : rw_cells psegs m (SP + 24) (x1_slots DT).
  Notation INV m1 cells := (x1f_inv m m1 DT SY js jt syms ncells cells).

  Notation ST pc mm w u sym x1 x5 x6 x7 x13 x17 x18 x21 x22 x23 x24 x25 x26 x27 x28 x30 x31 :=
    (MS (mkR x1 sp gp tp x5 x6 x7 (Z_to_bv 64 WK) (Z_to_bv 64 DT) (Z_to_bv 64 3) (Z_to_bv 64 (tl + 1)) (Z_to_bv 64 SY) x13
             (Z_to_bv 64 u) (Z_to_bv 64 sym) (Z_to_bv 64 (tl + 1)) x17 x18 (Z_to_bv 64 X1REP) (Z_to_bv 64 w) x21 x22 x23
             x24 x25 x26 x27 x28 (Z_to_bv 64 1) x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  Lemma fw_loop : forall f w cells u sym m1 (x1 x5 x6 x7 x13 x17 x18 x21 x22 x23 x24 x25 x26 x27 x28 x30 x31 : word) r,
    fill_weights f w tl rank syms cells sym u = Ok r -> Z.of_nat f = tl + 1 - w -> 1 <= w <= tl ->
    0 <= sym <= 256 -> 0 <= u <= Z.of_nat ncells ->
    INV m1 cells ->
    (forall m2 u' sym' (y1 y5 y6 y7 y13 y17 y18 y21 y22 y23 y24 y25 y26 y27 y28 y30 y31 : word),
       INV m2 r ->
       evt psegs POST (ST 0x139ec m2 (tl + 1) u' sym' y1 y5 y6 y7 y13 y17 y18 y21 y22 y23 y24 y25 y26 y27 y28 y30 y31)) ->
    evt psegs POST (ST 0x136f4 m1 w u sym x1 x5 x6 x7 x13 x17 x18 x21 x22 x23 x24 x25 x26 x27 x28 x30 x31).
Proof.
